"use strict";(self.webpackChunkwww=self.webpackChunkwww||[]).push([[98296],{10898:(e,t,n)=>{n.r(t),n.d(t,{assets:()=>a,contentTitle:()=>o,default:()=>c,frontMatter:()=>i,metadata:()=>r,toc:()=>d});var h=n(31085),s=n(71184);const i={sidebar_position:24,slug:"/bible/Luke/Luke_24",title:"Luke 24",hide_table_of_contents:!0},o="Luke",r={id:"bible/Luke/Luke 24",title:"Luke 24",description:"Chapter 24",source:"@site/docs/bible/Luke/Luke 24.md",sourceDirName:"bible/Luke",slug:"/bible/Luke/Luke_24",permalink:"/bibleNotes/docs/bible/Luke/Luke_24",draft:!1,unlisted:!1,editUrl:"https://github.com/ozkey/bibleNotes/tree/main/packages/www/docs/bible/Luke/Luke 24.md",tags:[],version:"current",sidebarPosition:24,frontMatter:{sidebar_position:24,slug:"/bible/Luke/Luke_24",title:"Luke 24",hide_table_of_contents:!0},sidebar:"bibleSidebar",previous:{title:"Luke 23",permalink:"/bibleNotes/docs/bible/Luke/Luke_23"},next:{title:"John",permalink:"/bibleNotes/docs/bible/John/"}},a={},d=[{value:"Chapter 24",id:"chapter-24",level:2}];function l(e){const t={admonition:"admonition",h1:"h1",h2:"h2",p:"p",...(0,s.R)(),...e.components},{BibleText:n}=t;return n||function(e,t){throw new Error("Expected "+(t?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}("BibleText",!0),(0,h.jsxs)(h.Fragment,{children:[(0,h.jsx)(t.h1,{id:"luke",children:"Luke"}),"\n",(0,h.jsx)(t.h2,{id:"chapter-24",children:"Chapter 24"}),"\n",(0,h.jsx)(t.p,{children:"Christ's resurrection and manifestation of himself to his disciples."}),"\n",(0,h.jsx)(n,{verse:1,children:"And on the first day of the week, very early in the morning, they came to the sepulchre, bringing the spices which they had prepared."}),"\n",(0,h.jsx)(n,{verse:2,children:"And they found the stone rolled back from the sepulchre."}),"\n",(0,h.jsx)(n,{verse:3,children:"And going in, they found not the body of the Lord Jesus."}),"\n",(0,h.jsx)(n,{verse:4,children:"And it came to pass, as they were astonished in their mind at this, behold, two men stood by them, in shining apparel."}),"\n",(0,h.jsx)(n,{verse:5,children:"And as they were afraid and bowed down their countenance towards the ground, they said unto them: Why seek you the living with the dead?"}),"\n",(0,h.jsx)(n,{verse:6,children:"He is not here, but is risen. Remember how he spoke unto you, when he was yet in Galilee,"}),"\n",(0,h.jsx)(n,{verse:7,children:"Saying: The Son of man must be delivered into the hands of sinful men and be crucified and the third day rise again."}),"\n",(0,h.jsx)(n,{verse:8,children:"And they remembered his words."}),"\n",(0,h.jsx)(n,{verse:9,children:"And going back from the sepulchre, they told all these things to the eleven and to all the rest."}),"\n",(0,h.jsx)(n,{verse:10,children:"And it was Mary Magdalen and Joanna and Mary of James and the other women that were with them, who told these things to the apostles."}),"\n",(0,h.jsx)(n,{verse:11,children:"And these words seemed to them as idle tales: and they did not believe them."}),"\n",(0,h.jsx)(n,{verse:12,children:"But Peter rising up, ran to the sepulchre and, stooping down, he saw the linen cloths laid by themselves: and went away wondering in himself at that which was come to pass."}),"\n",(0,h.jsx)(n,{verse:13,children:"And behold, two of them went, the same day, to a town which was sixty furlongs from Jerusalem, named Emmaus."}),"\n",(0,h.jsx)(n,{verse:14,children:"And they talked together of all these things which had happened."}),"\n",(0,h.jsx)(n,{verse:15,children:"And it came to pass that while they talked and reasoned with themselves, Jesus himself also, drawing near, went with them."}),"\n",(0,h.jsx)(n,{verse:16,children:"But their eyes were held, that they should not know him."}),"\n",(0,h.jsx)(n,{verse:17,children:"And he said to them: What are these discourses that you hold one with another as you walk and are sad?"}),"\n",(0,h.jsx)(n,{verse:18,children:"And the one of them, whose name was Cleophas, answering, said to him: Art thou only a stranger in Jerusalem, and hast not known the things that have been done there in these days?"}),"\n",(0,h.jsx)(n,{verse:19,children:"To whom he said: What things? And they said: Concerning Jesus of Nazareth, who was a prophet, mighty in work and word before God and all the people."}),"\n",(0,h.jsx)(n,{verse:20,children:"And how our chief priests and princes delivered him to be condemned to death and crucified him."}),"\n",(0,h.jsx)(n,{verse:21,children:"But we hoped that it was he that should have redeemed Israel. And now besides all this, to-day is the third day since these things were done."}),"\n",(0,h.jsx)(n,{verse:22,children:"Yea and certain women also of our company affrighted us who, before it was light, were at the sepulchre,"}),"\n",(0,h.jsx)(n,{verse:23,children:"And not finding his body, came, saying that they had all seen a vision of angels, who say that he is alive."}),"\n",(0,h.jsx)(n,{verse:24,children:"And some of our people went to the sepulchre and found it so as the women had said: but him they found not."}),"\n",(0,h.jsx)(n,{verse:25,children:"Then he said to them: O foolish and slow of heart to believe in all things, Which the prophets have spoken."}),"\n",(0,h.jsx)(n,{verse:26,children:"Ought not Christ to have suffered these things and so, to enter into his glory?"}),"\n",(0,h.jsx)(n,{verse:27,children:"And beginning at Moses and all the prophets, he expounded to them in all the scriptures the things that were concerning him."}),"\n",(0,h.jsx)(n,{verse:28,children:"And they drew nigh to the town whither they were going: and he made as though he would go farther."}),"\n",(0,h.jsx)(n,{verse:29,children:"But they constrained him, saying: Stay with us, because it is towards evening and the day is now far spent. And he went in with them."}),"\n",(0,h.jsx)(n,{verse:30,children:"And it came to pass, whilst he was at table with them, he took bread and blessed and brake and gave to them."}),"\n",(0,h.jsx)(n,{verse:31,children:"And their eyes were opened: and they knew him. And he vanished out of their sight."}),"\n",(0,h.jsx)(n,{verse:32,children:"And they said one to the other: Was not our heart burning within us, whilst he spoke in the way and opened to us the scriptures?"}),"\n",(0,h.jsx)(n,{verse:33,children:"And rising up, the same hour, they went back to Jerusalem: and they found the eleven gathered together, and those that were with them,"}),"\n",(0,h.jsx)(n,{verse:34,children:"Saying: The Lord is risen indeed and hath appeared to Simon."}),"\n",(0,h.jsx)(n,{verse:35,children:"And they told what things were done in the way: and how they knew him in the breaking of bread."}),"\n",(0,h.jsx)(n,{verse:36,children:"Now, whilst they were speaking these things, Jesus stood in the midst of them and saith to them: Peace be to you. It is I: Fear not."}),"\n",(0,h.jsx)(n,{verse:37,children:"But they being troubled and frightened, supposed that they saw a spirit."}),"\n",(0,h.jsx)(n,{verse:38,children:"And he said to them: Why are you troubled, and why do thoughts arise in your hearts?"}),"\n",(0,h.jsx)(n,{verse:39,children:"See my hands and feet, that it is I myself. Handle, and see: for a spirit hath not flesh and bones, as you see me to have."}),"\n",(0,h.jsx)(n,{verse:40,children:"And when he had said this, he shewed them his hands and feet."}),"\n",(0,h.jsx)(n,{verse:41,children:"But while they yet believed not and wondered for joy, he said: Have you here any thing to eat?"}),"\n",(0,h.jsx)(n,{verse:42,children:"And they offered him a piece of a broiled fish and a honeycomb."}),"\n",(0,h.jsx)(n,{verse:43,children:"And when he had eaten before them, taking the remains, he gave to them."}),"\n",(0,h.jsx)(n,{verse:44,children:"And he said to them: These are the words which I spoke to you while I was yet with you, that all things must needs be fulfilled which are written in the law of Moses and in the prophets and in the psalms, concerning me."}),"\n",(0,h.jsx)(n,{verse:45,children:"Then he opened their understanding, that they might understand the scriptures."}),"\n",(0,h.jsx)(n,{verse:46,children:"And he said to them: Thus it is written, and thus it behoved Christ to suffer and to rise again from the dead, the third day:"}),"\n",(0,h.jsx)(n,{verse:47,children:"And that penance and remission of sins should be preached in his name, unto all nations, beginning at Jerusalem."}),"\n",(0,h.jsx)(n,{verse:48,children:"And you are witnesses of these things."}),"\n",(0,h.jsx)(n,{verse:49,children:"And I send the promise of my Father upon you: but stay you in the city till you be endued with power from on high."}),"\n",(0,h.jsx)(t.admonition,{type:"note",children:(0,h.jsx)(t.p,{children:"Note 1: The promise of my Father...that is, the Holy Ghost, whom Christ had promised that his Father and he would send, John 14. 26, and 17. 7."})}),"\n",(0,h.jsx)(n,{verse:50,children:"And he led them out as far as Bethania: and lifting up his hands, he blessed them."}),"\n",(0,h.jsx)(n,{verse:51,children:"And it came to pass, whilst he blessed them, he departed from them and was carried up to heaven."}),"\n",(0,h.jsx)(n,{verse:52,children:"And they adoring went back into Jerusalem with great joy."}),"\n",(0,h.jsx)(n,{verse:53,children:"And they were always in the temple, praising and blessing God. Amen."})]})}function c(e={}){const{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,h.jsx)(t,{...e,children:(0,h.jsx)(l,{...e})}):l(e)}},71184:(e,t,n)=>{n.d(t,{R:()=>o,x:()=>r});var h=n(14041);const s={},i=h.createContext(s);function o(e){const t=h.useContext(i);return h.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:o(e.components),h.createElement(i.Provider,{value:t},e.children)}}}]);